"""Generate portable static HTML for the existing GitHub Pages Jekyll workflow.
No template engine or third-party Python package is required. Run from repo root.
"""
from pathlib import Path
import html,json,zipfile
ROOT=Path(__file__).resolve().parents[1]
F=ROOT/'mekholi-family'
manifest=json.loads((F/'documentation/family-manifest.json').read_text())
repo='https://github.com/sisir-sinha/Mekholi-Fonts'
zipname='Mekholi-v1.0-experimental-18-styles.zip'
def esc(v):return html.escape(str(v))
def page(filename,title,body,active,description):
 nav=''.join('<a '+('class="active" aria-current="page" ' if key==active else '')+'href="'+url+'">'+label+'</a>' for key,url,label in [('home','./','Overview'),('docs','documentation.html','Documentation'),('license','license.html','License')])
 doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>'''+esc(title)+''' · Mekholi / মেখলি</title><meta name="description" content="'''+esc(description)+'''"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><meta property="og:title" content="'''+esc(title)+''' · Mekholi / মেখলি"><meta property="og:description" content="'''+esc(description)+'''"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap nav"><a class="brand" href="./">Mekholi <span lang="bn">মেখলি</span></a><nav aria-label="Main navigation">'''+nav+'''<a class="nav-play'''+(' active' if active=='play' else '')+'" '+('aria-current="page" ' if active=='play' else '')+'''href="playground.html">Playground ↗</a></nav></div></header><main class="wrap" id="main">'''+body+'''</main><footer><div class="wrap"><div class="footer-top"><a class="brand" href="./">Mekholi <span lang="bn">মেখলি</span></a><div class="footer-links"><a href="documentation.html">Read the guide</a><a href="mekholi-family/OFL.txt">OFL 1.1</a><a href="'''+repo+'''">GitHub ↗</a></div></div><p>Designed for the Mekholi project by Surajit Singha Sisir · Developed by Ningshing Che. Experimental Kalpurush derivative; not an original redraw or a production-certified family.</p><p>© 2026 Surajit Singha Sisir and Ningshing Che, for Mekholi modifications. Reserved Font Name: Mekholi. Upstream © 2022 Tanbin Islam Siyam; Reserved Font Name: Kalpurush. Latin based on Gentium. No upstream endorsement implied. Font Software and site additions: SIL OFL 1.1; see the applicable notices. The original third-party reference fonts are not relicensed by this site.</p></div></footer>'''+('<script src="assets/playground.js" defer></script>' if active=='play' else '')+'''</body></html>'''
 (ROOT/filename).write_text(doc)
def section(id,title,body):return '<section id="'+id+'"><h2>'+title+'</h2>'+body+'</section>'
def docpage(title,kicker,intro,sections):
 return '<div class="page-title"><div class="eyebrow">'+kicker+'</div><h1>'+title+'</h1><p class="lead">'+intro+'</p></div><div class="doc-layout"><aside class="toc" aria-label="On this page"><div class="eyebrow">On this page</div>'+''.join('<a href="#'+i+'">'+t+'</a>' for i,t,b in sections)+'</aside><article class="prose">'+''.join(section(i,t,b) for i,t,b in sections)+'</article></div>'
style_rows=''.join('<tr><td>'+str(m['weight'])+'</td><td>'+esc(m['style'])+'</td><td><a href="mekholi-family/fonts/ttf/'+m['file']+'">'+esc(m['file'])+'</a></td></tr>' for m in manifest)
weight_rows=''.join('<div class="type-row"><div class="type-label">'+esc(m['style'])+'<br>'+str(m['weight'])+' · '+('12° slant' if m['italic'] else 'Upright')+'</div><div class="font" lang="bpy" style="font-weight:'+str(m['weight'])+';font-style:'+('italic' if m['italic'] else 'normal')+'">মেখলি · অ আ ক র ক্ষ জ্ঞ</div></div>' for m in manifest if not m['italic'])
home='''<div class="hero"><div><span class="badge"><span class="dot"></span> Version 1.0 · Experimental family</span><h1>Mekholi</h1><div class="native" lang="bn">মেখলি</div><p class="lead">A serif font project for Bishnupriya Manipuri.<br>Eighteen styles. An open foundation. Room to grow.</p><div class="actions"><a class="btn" href="downloads/'''+zipname+'''" download>Download the family ↓</a><a class="btn secondary" href="playground.html">Try the playground ↗</a></div><p class="tiny">TTF for desktop &amp; print · WOFF / WOFF2 for the web · SIL OFL 1.1</p></div><div class="hero-right"><div class="eyebrow">A study in Bengali-script form</div><div class="hero-glyph" lang="bpy">মেখলি</div><div><div class="hero-rule"></div><p class="font" lang="bpy" style="font-size:32px;margin:20px 0">অ আ ক খ র ৱ ৰ ক্ষ জ্ঞ</p><div class="tiny">Mekholi Regular / 400 / Serif</div></div></div></div><div class="stats"><div class="stat"><strong>18</strong><span>Static styles · upright &amp; slanted</span></div><div class="stat"><strong>100–900</strong><span>Nine experimental weights</span></div><div class="stat"><strong>586</strong><span>Glyphs per style</span></div><div class="stat"><strong>OFL 1.1</strong><span>Open font license</span></div></div><div class="notice"><strong>A transparent starting point.</strong> Mekholi currently derives from Kalpurush. Its base is 3% wider; additional weights are mechanically generated and italic-labelled styles are slanted uprights. Distinctive redraws, native-language approval and optical refinement are still ahead.</div><section class="section"><div class="section-head"><div><div class="eyebrow">Built to explore</div><h2>From a first specimen to a working page.</h2></div><a href="documentation.html">Read the complete guide ↗</a></div><div class="grid3"><article class="card"><span class="number">01 / EXPERIMENT</span><h3>A live type playground</h3><p>Bring your own text. Adjust all nine weights, slant, size, spacing and colors. Inspect character coverage and export a PNG proof.</p><a href="playground.html">Start typesetting ↗</a></article><article class="card"><span class="number">02 / IMPLEMENT</span><h3>Desktop, web &amp; print</h3><p>Install TTF files, self-host compressed web fonts, or copy a CSS recipe. Understand what has been tested—and what still needs review.</p><a href="documentation.html#web">Use Mekholi ↗</a></article><article class="card"><span class="number">03 / UNDERSTAND</span><h3>Open, with clear attribution</h3><p>The full OFL travels inside every font. Read the copyright notices, reserved names and practical rules for redistribution and modification.</p><a href="license.html">Explore the license ↗</a></article></div></section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">The weight spectrum</div><h2>Nine weights. One experimental family.</h2></div><a href="playground.html">Compare all 18 styles ↗</a></div>'''+weight_rows+'''<p class="tiny" style="margin-top:20px">Bengali-script repertoire specimens, not a native-language orthographic proof. All italic-labelled styles are available in the playground.</p></section><div class="bottom-cta"><div><h2>Make room for your own words.</h2><p style="margin:0">Try a real Bishnupriya Manipuri sample and help shape the next iteration.</p></div><a class="btn" href="playground.html">Open playground ↗</a></div>'''
page('index.html','An open serif in progress',home,'home','Mekholi / মেখলি: an experimental 18-style serif family for Bishnupriya Manipuri. Download fonts, explore documentation and try the live playground.')
docs=[
('about','1. About Mekholi','''<p><strong>Mekholi</strong>, displayed in Bengali as <strong lang="bn" class="font">মেখলি</strong>, is a serif font project intended for Bishnupriya Manipuri in the Bengali/Assamese script. Its internal font-family name remains <code>Mekholi</code>; the Bengali display name does not change the installable family name.</p><ul><li><strong>Designer:</strong> Surajit Singha Sisir</li><li><strong>Developer:</strong> Ningshing Che</li><li><strong>Version:</strong> 1.0 / Experimental Family 1</li><li><strong>Targets:</strong> web and print media</li><li><strong>Formats:</strong> static TTF, WOFF and WOFF2</li></ul><div class="notice"><strong>Not a finished original typeface.</strong> This is a Kalpurush-derived experiment. The first Regular changes width and engineering, not its underlying design vocabulary. Language-specific validation has not been completed.</div>'''),
('download','2. Download & package contents','''<p><a class="btn" href="downloads/'''+zipname+'''" download>Download all 18 styles ↓</a></p><p>The ZIP contains 54 font files (18 of each format), web CSS, visual proofs, source input, build tools, validation reports and license documents. No installer, tracker or online font subscription is required.</p><div class="table-wrap"><table><tr><th>Path</th><th>Purpose</th></tr><tr><td><code>fonts/ttf/</code></td><td>Installable desktop and print fonts</td></tr><tr><td><code>fonts/web/</code></td><td>WOFF/WOFF2 and the family @font-face stylesheet</td></tr><tr><td><code>source/</code></td><td>Upstream input and reproducible font-generation tools</td></tr><tr><td><code>documentation/</code></td><td>Provenance, manifest, validation and file hashes</td></tr><tr><td><code>specimens/</code></td><td>Standalone preview and raster PNG/PDF proof sheets</td></tr><tr><td><code>OFL.txt</code>, <code>OFL-FAQ.txt</code>, <code>FONTLOG.txt</code></td><td>License, FAQ and changes</td></tr></table></div><p>The repository’s original <code>ttf/</code> reference files are separate third-party fonts, not Mekholi outputs. The Mekholi OFL notice does not relicense SutonnyOMJ.</p>'''),
('styles','3. All 18 styles','''<p>Each weight is a separate static font, with upright and italic-labelled versions. There is no continuous variable axis or variable-font file. Click a filename to download an individual TTF.</p><div class="table-wrap"><table><tr><th>Weight</th><th>Style</th><th>Desktop font</th></tr>'''+style_rows+'''</table></div><p>The Thin–Black labels are experimental assignments, not optically calibrated master weights. “Italic” denotes a mechanical 12° slant of upright letterforms, not a newly drawn true italic.</p>'''),
('desktop','4. Install on desktop','''<h3>Windows</h3><ol><li>Extract the ZIP. Select the desired files in <code>fonts/ttf/</code>.</li><li>Right-click and choose <strong>Install</strong>, or open them in the Windows font installer.</li><li>Restart your design or document application and choose Mekholi.</li></ol><h3>macOS</h3><p>Open the TTF files in Font Book and install them. Resolve duplicate or old Mekholi test builds before using a replacement.</p><h3>Linux</h3><p>Copy the TTF files to <code>~/.local/share/fonts/Mekholi/</code> and refresh the font cache:</p><pre><code>mkdir -p ~/.local/share/fonts/Mekholi
# Copy the desired TTF files to that directory, then:
fc-cache -f</code></pre><p>Modern apps should group styles using typographic names. Older apps may list weight-specific families such as <em>Mekholi Thin</em>, with Regular/Italic links. Do not install both the earlier standalone prototype and the current family Regular at once.</p>'''),
('web','5. Self-host on the web','''<p>Copy the complete <code>fonts/web/</code> directory, preserving the relative paths inside <code>mekholi.css</code>. Prefer WOFF2; WOFF is provided as an alternative. TTF is primarily the desktop format.</p><pre><code>&lt;link rel="stylesheet" href="fonts/web/mekholi.css"&gt;
&lt;p class="mekholi" lang="bpy"&gt;মেখলি&lt;/p&gt;</code></pre><pre><code>.mekholi {
  font-family: 'Mekholi', serif;
  font-weight: 400;
  font-style: normal;
  font-synthesis: none;
  line-height: 1.75;
}
h1.mekholi { font-weight: 700; }
em.mekholi { font-style: italic; }</code></pre><p>Use <code>lang="bpy"</code> for actual Bishnupriya Manipuri content and appropriate language tags for other content. Declaring a language is not proof that the font covers its entire orthography.</p><h3>Load only what you need</h3><p>The stylesheet declares 18 faces, but browsers normally fetch only those used. For a site using only Regular and Bold, you can retain just those declarations. Keep the OFL and notices with redistributed font assets.</p><pre><code>@font-face {
  font-family: 'Mekholi';
  src: url('./Mekholi-Regular.woff2') format('woff2'),
       url('./Mekholi-Regular.woff') format('woff');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}</code></pre><p>Serve fonts with correct MIME types (<code>font/woff2</code>, <code>font/woff</code>, <code>font/ttf</code>). If hosting on another origin, configure CORS. Avoid absolute domain-root paths on GitHub project Pages: relative paths keep the <code>/Mekholi-Fonts/</code> prefix intact.</p>'''),
('print','6. Print & document workflow','''<p>Use the TTF files in a Unicode-aware application. Select explicit shipped weights instead of synthetic bold or slant. Before publication:</p><ol><li>Check every language-specific letter, conjunct and mark using native-language text.</li><li>Review small text at the actual printed size. Thin details can disappear; heavy counters can close.</li><li>Check line spacing and clipping, especially below-base vowel signs and stacked marks.</li><li>Export a PDF with the chosen fonts embedded; inspect the PDF’s font list and glyph output.</li><li>Make a physical proof on the intended paper and printing process.</li></ol><p>The supplied PDF specimen is a <strong>raster proof sheet</strong>, not an embedded-font PDF or a prepress/PDF-X certification. No production press test has been completed.</p>'''),
('coverage','7. Script & character coverage','''<p>Every style retains <strong>586 glyphs</strong> and <strong>210 directly mapped Unicode code points</strong> from the upstream coverage, including basic Latin letters, ASCII and Bengali digits, and much of the Bengali/Assamese script. Unicode coverage is not the same as language completeness.</p><p>Known missing assigned Bengali-block code points include <code>U+0980</code>, <code>U+09FB</code>, <code>U+09FC</code>, <code>U+09FD</code> and <code>U+09FE</code>. No new language-specific glyphs or conjunct designs were added.</p><p><a href="assets/coverage.json">Download the mapped code-point list (JSON)</a>. The playground checks typed characters against this list. It treats whitespace and ZWJ/ZWNJ separately. The checker is deliberately a direct-cmap test: normalization, variation sequences and complex shaping may require further interpretation.</p><p>Provide a verified Bishnupriya Manipuri alphabet and corpus, including any required use of ৰ/ৱ, punctuation, numerals and uncommon conjuncts, before claiming complete language support.</p>'''),
('shaping','8. Bengali shaping & spacing','''<p>The family inherits Kalpurush’s <code>beng</code> and <code>bng2</code> OpenType shaping support, including GSUB substitutions and GPOS mark positioning. The initial 3% horizontal expansion was applied consistently to outlines, advances and horizontal positioning.</p><p>Mechanical weights retain the initial advances, with recalculated outline sidebearings. Italic-labelled fonts shear positioning anchors and placement offsets to follow the slanted outlines. Their spacing and mark relationships have not received a full optical redesign.</p><p>Current shared metrics: hhea/typo ascent <strong>1100</strong>, descent <strong>-650</strong>, line gap <strong>0</strong>; Windows ascent <strong>1300</strong>, descent <strong>700</strong>; units per em <strong>1000</strong>. A web line-height of <code>1.75</code> is a starting point, not a requirement for every layout.</p><p>Do not insert spaces inside conjuncts or strip virama/joiners to “fix” rendering. Use a modern shaping engine. Letter-spacing can disrupt the intended rhythm of connected script; use it sparingly.</p>'''),
('playground','9. Playground guide','''<p><a href="playground.html">Open the live sandbox</a> to paste text, select a weight and slant, change size/leading/tracking/alignment and choose foreground/background colors.</p><ul><li><strong>Presets:</strong> the supplied name, script repertoire, marks/conjuncts, digits or Latin—not invented native prose.</li><li><strong>Coverage notice:</strong> lists unmapped code points that may display in a fallback font.</li><li><strong>Copy CSS:</strong> copies the selected settings; first load the web-font CSS on your own site.</li><li><strong>Share:</strong> encodes up to 1,500 characters in the URL fragment. The app does not upload your sample.</li><li><strong>Export PNG:</strong> generates a 2× raster proof locally after loading the selected font. Wrapping can differ from the DOM preview; long unbreakable sequences can overflow.</li><li><strong>Reset:</strong> restores defaults and clears the shared URL fragment.</li></ul><p>No server-side text storage, analytics or external font CDN is used by the site. GitHub Pages still receives normal asset/page requests. Anyone you share a sample link with can read its text; do not put confidential text in shared links. Rendering and clipboard behavior depend on your browser and security context.</p>'''),
('validation','10. Validation & known limitations','''<p><a href="mekholi-family/documentation/validation.json">Read the full machine-readable report</a>. The current font build passed 4,103 representative/synthetic strings per style, <strong>73,854 cases total</strong>.</p><ul><li>TTF table and full-file checksums pass; outlines load with no newly empty glyphs.</li><li>Coverage and glyph selection/cluster mapping match upstream.</li><li>No missing output glyphs or overflow beyond the chosen Windows vertical metrics occurred in the tested corpus.</li><li>License, weight, style and embedding metadata were checked; WOFF/WOFF2 reopen with matching cmap and glyph order.</li></ul><div class="notice"><strong>“Pass” is limited to those checks.</strong> It does not certify every conjunct, collision, contour, stacked mark, hinting behavior, optical weight, browser, operating system or printing workflow. Grid-fitting instructions were removed, not regenerated. Native-language review is still required.</div>'''),
('build','11. Rebuild & contribute','''<p>The bundle includes the original upstream input and Python build tools. On Linux, install Python 3.11+ and the FreeType shared library, then run from the family directory:</p><pre><code>cd mekholi-family
pip install -r source/requirements.txt
python source/build_family.py
python source/validate_family.py</code></pre><p>The build uses fontTools, FreeType contour offsets, Skia PathOps cleanup, Brotli and HarfBuzz validation. It produces static fonts; the input is a binary font, not an original multi-master design source. The exact dependency versions are pinned in <code>source/requirements.txt</code>.</p><p>To regenerate the documentation pages and ZIP from the repository root:</p><pre><code>python tools/build_site.py
python tools/check_site.py</code></pre><p>Report issues with the exact text/code points, style, size, application/version, operating system and a screenshot or PDF. Suggested next work: a verified language corpus, distinct letterform redraws, optical weight masters, real italic designs, refined spacing, hinting and platform/press tests.</p><p><a href="'''+repo+'''/issues">Open an issue on GitHub ↗</a></p>'''),
('troubleshooting','12. Troubleshooting','''<h3>Boxes or unexpected letterforms</h3><p>Check the playground’s unmapped-character list and use a Unicode-aware shaping application. A browser may substitute another font silently. The font does not support every script or symbol.</p><h3>Wrong weight or italic</h3><p>Ensure the requested file is present, the CSS has matching weight/style declarations, and the browser network panel shows no 404/CORS errors. Disable synthetic styles when comparing actual files.</p><h3>Old design still appears</h3><p>Remove duplicate prototype installs, restart the app, refresh font caches where appropriate, and hard-refresh the website. Desktop font caches and browser caches are separate.</p><h3>Marks clip or lines overlap</h3><p>Increase line-height, remove fixed-height clipping/overflow, and test a current text engine. Record the exact code-point sequence for a bug report.</p><h3>Playground does not load from a downloaded HTML file</h3><p>This site uses local font and JSON requests. Serve the repository through HTTP, for example <code>python -m http.server 8000</code>, then open it in a browser. The separate bundled specimen HTML has embedded fonts and is designed for standalone viewing.</p>'''),
('credits','13. Credits, license & history','''<p>Mekholi project design credit: <strong>Surajit Singha Sisir</strong>. Developer: <strong>Ningshing Che</strong>. These credits cover project contributions; they do not replace authorship of inherited outlines.</p><p>Upstream: Kalpurush by Md. Tanbin Islam Siyam, developed under the Avro Font Development Project; Latin based on Gentium. The supplied Kalpurush 0.258 input matches the author repository’s release byte-for-byte. Its repository LICENSE says OFL 1.1; older font metadata and README say 1.0. This discrepancy is preserved in the <a href="mekholi-family/documentation/PROVENANCE.md">provenance record</a>, rather than concealed.</p><p>SutonnyOMJ was not used in Mekholi. Its redistribution permissions remain unresolved.</p><p>See <a href="license.html">the complete licensing guide</a>, <a href="mekholi-family/FONTLOG.txt">FONTLOG</a>, <a href="mekholi-family/OFL.txt">OFL.txt</a> and <a href="mekholi-family/OFL-FAQ.txt">the official OFL FAQ</a>. Version 1.0 is the project version, not production approval.</p>''')]
page('documentation.html','Documentation',docpage('The Mekholi guide.','Documentation / Version 1.0','Install it, put it on the web, inspect its limits, and understand the path from this prototype to a finished family.',docs),'docs','Comprehensive Mekholi documentation: installation, 18 font styles, web CSS, print workflow, coverage, shaping, validation, rebuilding and troubleshooting.')
licenses=[
('summary','1. Which license applies?','''<p>The generated Mekholi Font Software is released under the <strong>SIL Open Font License, Version 1.1</strong>. The full English license—not this summary—is authoritative. Its text is included in every output font’s License field and as <a href="mekholi-family/OFL.txt">OFL.txt</a> in the bundle.</p><div class="notice">This is practical project documentation, not legal advice, an ownership audit, SIL approval or registration. The OFL website’s <a href="https://openfontlicense.org/ofl-fonts/">font showcase</a> is not a licensing registration service.</div><p><a class="btn" href="mekholi-family/OFL.txt" download>Download OFL.txt ↓</a> <a href="https://openfontlicense.org/open-font-license-official-text/">Official OFL 1.1 text ↗</a></p>'''),
('notices','2. Copyright & authorship','''<div class="card"><p>Copyright (c) 2022, Tanbin Islam Siyam (https://omicronlab.com), with Reserved Font Name <strong>Kalpurush</strong>.</p><p style="margin-bottom:0">Copyright (c) 2026, Surajit Singha Sisir and Ningshing Che, for the Mekholi modifications, with Reserved Font Name <strong>Mekholi</strong>.</p></div><p>The project owner confirmed both named contributors as the copyright holders for the modifications and chose to reserve Mekholi. This notice does not transfer or overwrite the upstream copyright. Original Bengali design and development: Md. Tanbin Islam Siyam / Avro Font Development Project; Latin based on Gentium. Acknowledgments do not imply endorsement.</p>'''),
('permissions','3. Use in websites, books & commercial work','''<div class="table-wrap"><table><tr><th>Activity</th><th>Practical rule</th></tr><tr><td>Personal or commercial documents, graphics and print work</td><td>Allowed. Documents made with the font do not have to use the OFL.</td></tr><tr><td>Self-hosting or embedding web fonts</td><td>Allowed. Preserve the OFL and notices with distributed font assets.</td></tr><tr><td>Embedding in PDFs, e-books, apps or other software</td><td>Allowed under the OFL’s terms; include required notices/license when distributing the Font Software.</td></tr><tr><td>Bundling fonts with commercial software</td><td>Allowed while preserving the font’s OFL license and required notices.</td></tr><tr><td>Selling the font file by itself</td><td>Not allowed under OFL condition 1.</td></tr><tr><td>Changing the font and redistributing the result</td><td>Allowed under the OFL; retain notices, keep the OFL, and respect Reserved Font Names.</td></tr><tr><td>Claiming that upstream authors endorse your modified font</td><td>Not allowed without permission; factual attribution is permitted.</td></tr></table></div><p>You do not have to place a font credit in every image or document merely because you used the font. Distinguish using a font to create a document from redistributing the font files themselves.</p>'''),
('rfn','4. Reserved Font Names','''<p><strong>Mekholi</strong> is a Reserved Font Name for this project. <strong>Kalpurush</strong> remains an upstream Reserved Font Name.</p><p>When distributing a modified version, do not use a reserved name as its primary user-visible font name unless you have explicit written permission from the corresponding copyright holder(s). Change the internal family, full and PostScript names consistently; retain the copyright/RFN notices in attribution.</p><p>Using unmodified Mekholi in your website, artwork or document does <strong>not</strong> require renaming it. An RFN is an OFL naming condition; it is not proof of a registered trademark, uniqueness of the design, or SIL certification. For edge cases such as format conversion and technical subsetting, consult the <a href="https://openfontlicense.org/ofl-reserved-font-names/">official RFN guidance</a>.</p>'''),
('redistribution','5. Redistribute or make a derivative','''<ol><li>Keep the relevant copyright statements, Reserved Font Name declarations and complete OFL 1.1 text with the Font Software.</li><li>If you modify and redistribute it, use a new primary family name unless the corresponding rights holders give permission to retain reserved names.</li><li>Describe your actual contributions and retain accurate upstream attribution. Add a contribution-specific copyright notice if appropriate.</li><li>Keep the modified Font Software under the OFL. Do not impose a conflicting proprietary license or sell a font component by itself.</li><li>Update the internal copyright, licensing and naming metadata, package notices and FONTLOG as applicable.</li></ol><p>The OFL does not require you to publish private modifications or distribute source simply because you make a change. If you do redistribute Font Software, its license conditions apply. Read the full license and FAQ for your distribution scenario.</p><p><a href="https://openfontlicense.org/how-to-modify-ofl-fonts/">Official modification guidance ↗</a></p>'''),
('metadata','6. What is embedded in the fonts?','''<div class="table-wrap"><table><tr><th>Field</th><th>Mekholi value</th></tr><tr><td>Name ID 0 — copyright</td><td>Upstream notice plus contribution-specific 2026 copyright and RFNs</td></tr><tr><td>Name ID 8 — manufacturer/developer</td><td>Ningshing Che</td></tr><tr><td>Name ID 9 — designer</td><td>Surajit Singha Sisir</td></tr><tr><td>Name ID 13 — license</td><td>Complete bundled OFL.txt, including its copyright/RFN header</td></tr><tr><td>Name ID 14 — license URL</td><td>https://openfontlicense.org/</td></tr><tr><td>OS/2 fsType</td><td>0 — no technical embedding restriction signaled</td></tr></table></div><p>The metadata is present in TTF, WOFF and WOFF2. <code>fsType=0</code> is a technical embedding flag, not an independent copyright license or permission to ignore the OFL. Designer and developer credits do not by themselves establish ownership.</p>'''),
('provenance','7. Upstream provenance & scope','''<p>The original source is Kalpurush 0.258 from <a href="https://github.com/potasiyam/Kalpurush">the author’s repository</a>, inspected at commit <code>212bef1414db954b9259f099c0fdbad5cd95a80e</code>. The source font SHA-256 is:</p><pre><code>83613a03e53aad8337f2be9fb974409a23c1d99b3b4b494567ba9d156c492b01</code></pre><p>The upstream repository LICENSE explicitly states OFL 1.1 and the Reserved Font Name Kalpurush. Historical name records and README still state OFL 1.0. This build relies on the explicit license accompanying the author’s identical release and retains the old source/README for transparency. Obtain author confirmation if your publishing policy requires it.</p><p>The original reference files in the repository’s root <code>ttf/</code> directory are not automatically covered by Mekholi’s new notice. In particular, SutonnyOMJ was not used, and its rights remain unresolved. This site does not relicense it or assert that the whole repository is third-party-rights-cleared.</p><p><a href="mekholi-family/documentation/PROVENANCE.md">Read the provenance record</a> · <a href="https://github.com/sisir-sinha/Mekholi-Fonts/blob/main/mekholi-family/source/OFL-upstream.txt">Original upstream license</a></p>'''),
('full-text','8. Complete bundled license','''<p>The copyright/RFN header is project-specific. The OFL 1.1 terms below it are retained unchanged from the upstream license.</p><pre class="license-full">'''+esc((F/'OFL.txt').read_text())+'''</pre>'''),
('resources','9. Official references & documents','''<ul><li><a href="https://openfontlicense.org/how-to-apply-the-ofl/">Applying the OFL to fonts</a></li><li><a href="https://openfontlicense.org/how-to-modify-ofl-fonts/">Modifying and redistributing OFL fonts</a></li><li><a href="https://openfontlicense.org/open-font-license-official-text/">Authoritative English OFL 1.1 text</a></li><li><a href="https://openfontlicense.org/ofl-faq/">Official OFL FAQ</a> · <a href="mekholi-family/OFL-FAQ.txt">Bundled FAQ text</a></li><li><a href="mekholi-family/FONTLOG.txt">Mekholi FONTLOG</a></li><li><a href="mekholi-family/OFL.txt">Mekholi OFL.txt</a></li></ul><p>The font is supplied without warranty as described in the license. The practical use of an experimental build still requires appropriate language, design and production checks.</p>''')]
page('license.html','License & attribution',docpage('Open by design.<br>Clear about its roots.','License / SIL OFL 1.1','What you can do with Mekholi, what travels with the font, and why attribution and reserved names matter.',licenses),'license','Mekholi OFL 1.1 license guide: full license, copyright, reserved names, embedding, commercial use, redistribution and Kalpurush provenance.')
play='''<div class="page-title"><div class="eyebrow">Live type sandbox / 18 static styles</div><h1>Your words. In <span class="font" lang="bn">মেখলি</span>.</h1><p class="lead">Explore the family in your browser. Paste a real language sample, compare the weights, and export a proof.</p></div><div class="play-layout"><aside class="controls" aria-label="Typography controls"><div class="control wide"><label for="preset">Sample presets</label><select id="preset"><option value="">Custom / initial sample</option><option value="name">Mekholi / মেখলি</option><option value="alphabet">Script repertoire</option><option value="marks">Vowel signs &amp; conjuncts</option><option value="numbers">Numerals &amp; currency</option><option value="latin">Latin coverage</option></select></div><div class="control wide"><label for="text">Your text</label><textarea id="text" lang="bpy" spellcheck="false" maxlength="20000" aria-describedby="sample-note"></textarea><div class="tiny" id="sample-note">Presets are repertoire tests, not verified Bishnupriya Manipuri prose.</div></div><div class="control"><label for="weight">Weight</label><select id="weight">'''+''.join('<option value="'+str(m['weight'])+'">'+str(m['weight'])+' · '+esc(m['style'])+'</option>' for m in manifest if not m['italic'])+'''</select></div><div class="control"><label for="style">Style</label><select id="style"><option value="normal">Upright</option><option value="italic">Slanted italic · 12°</option></select></div><div class="control wide"><label for="size">Font size <output id="size-value" for="size">48 px</output></label><input id="size" type="range" min="16" max="120" step="1" value="48"></div><div class="control"><label for="leading">Line height <output id="leading-value" for="leading">1.75</output></label><input id="leading" type="range" min="1" max="2.6" step="0.05" value="1.75"></div><div class="control"><label for="tracking">Tracking <output id="tracking-value" for="tracking">0 px</output></label><input id="tracking" type="range" min="-1" max="5" step="0.1" value="0"></div><div class="control wide"><label for="align">Alignment</label><select id="align"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></div><div class="control"><label for="color">Text color</label><input id="color" type="color" value="#193b35"></div><div class="control"><label for="background">Paper color</label><input id="background" type="color" value="#fffef9"></div><div class="wide tiny">Tracking may affect connected-script rhythm. Native-language and optical review are still needed.</div></aside><div><div class="toolbar"><span class="eyebrow">Live specimen</span><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn secondary" id="reset" type="button">Reset</button><button class="btn secondary" id="share" type="button">Share link</button><button class="btn" id="export" type="button">Export PNG ↓</button></div></div><div class="canvas-wrap"><div class="canvas-top"><span id="style-label">400 / upright</span><span id="font-status" role="status">Loading Mekholi…</span></div><div id="preview" class="preview" lang="bpy" aria-label="Live font specimen"></div><div class="canvas-caption">Version 1.0 · Experimental Kalpurush derivative · Serif · No synthetic browser styles</div></div><div class="status" id="status" role="status" aria-live="polite"></div><div id="coverage" class="coverage" role="status" aria-live="polite">Loading character coverage…</div><div class="notice"><strong>Know what you’re comparing.</strong> Weights are mechanical contour offsets. Italic-labelled styles are 12° slanted uprights, not true drawn italics. The browser may use fallback for unmapped characters. PNG is a raster proof, not a print certification.</div><div class="code-panel"><div class="toolbar"><h3 style="margin:0">Your CSS settings</h3><button class="btn secondary" id="copy-css" type="button">Copy CSS</button></div><p class="tiny">First load <code>fonts/web/mekholi.css</code> on your site. These settings alone do not load the font.</p><pre><code id="css-output" tabindex="0"></code></pre></div><p class="tiny">Your text stays in this page unless you copy or share it. Share links contain the sample in a URL fragment; anyone with the link can read it. No analytics, text upload or external font service is used. <a href="documentation.html#playground">Playground details ↗</a></p><noscript><div class="notice">JavaScript is required for the interactive playground. See <a href="mekholi-family/specimens/Mekholi-family.png">the static family specimen</a> instead.</div></noscript></div></div>'''
page('playground.html','Font playground',play,'play','Try Mekholi / মেখলি in a live browser playground: all 18 styles, custom text, coverage checks, CSS, shareable samples and PNG export.')
# Keep downloadable package current, excluding Python caches and excluding this website.
(ROOT/'downloads').mkdir(exist_ok=True)
with zipfile.ZipFile(ROOT/'downloads'/zipname,'w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(F.rglob('*')):
  if p.is_file() and '__pycache__' not in p.parts:z.write(p,'Mekholi-v1.0-experimental/'+str(p.relative_to(F)))
print('Built four static pages and downloadable family ZIP.')
